import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'web-development';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        setLoading(true);
        const res = await fetch("http://localhost:5000/api/quiz/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ domain })
        });

        if (!res.ok) throw new Error("Failed to fetch");
        
        const data = await res.json();
        setQuestions(data);
      } catch (err) {
        setError("Could not generate quiz. Please try again.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchQuestions();
  }, [domain]);

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-64 space-y-4">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-500"></div>
      <p className="text-slate-600 font-medium">AI is crafting your {domain} quiz...</p>
    </div>
  );

  if (error) return (
    <div className="p-8 text-center bg-red-50 rounded-3xl border border-red-200">
      <p className="text-red-600">{error}</p>
      <Button className="mt-4" onClick={() => window.location.reload()}>Retry</Button>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto space-y-8 p-4">
      <div className="rounded-[2rem] border bg-white p-8 shadow-xl">
        <h2 className="text-3xl font-bold capitalize mb-6">{domain.replace(/-/g, ' ')} Quiz</h2>
        
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-3xl bg-slate-50 border border-slate-100">
              <p className="text-lg font-semibold mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map((opt) => (
                  <button
                    key={opt}
                    disabled={submitted}
                    onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                    className={`p-4 text-left rounded-2xl border transition-all ${
                      selected[idx] === opt 
                        ? 'bg-teal-600 text-white border-teal-600 shadow-md' 
                        : 'bg-white hover:border-teal-400 text-slate-700'
                    } ${submitted && opt === q.answer ? 'ring-2 ring-green-500 bg-green-50' : ''}`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-10 border-t pt-6">
          {!submitted ? (
            <Button 
              onClick={() => setSubmitted(true)} 
              disabled={Object.keys(selected).length < questions.length}
              className="w-full sm:w-auto"
            >
              Submit Results
            </Button>
          ) : (
            <Button onClick={() => navigate(`/roadmap/${domain}`)} className="w-full">
              Proceed to Roadmap →
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}
